import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  Grid,
  IconButton,
  InputLabel,
  LinearProgress,
  MenuItem,
  Select,
  Snackbar,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TextField,
  Typography
} from '@mui/material';
import {
  Assessment as ReportIcon,
  Download as DownloadIcon,
  Email as EmailIcon,
  Print as PrintIcon,
  Close as CloseIcon,
  Gavel as ComplianceIcon
} from '@mui/icons-material';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Legend,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis
} from 'recharts';
import ApiService from '../services/api';
import { BRAND_LOGO_SRC } from '../constants/brand';
import TabSectionNavLinks from './TabSectionNavLinks';

const REPORTING_TAB_LABELS = ['Overview', 'BRSR', 'ISO 14064', 'ISO 14067', 'CBAM'] as const;

type ExportFormat = 'brsr' | 'cbam' | 'iso14064' | 'iso14067';
type CbamComplianceStatus = 'On Track' | 'Needs Attention' | 'At Risk' | 'Not Required';
type CbamDocumentStatus = 'complete' | 'in_progress' | 'missing';
type CbamReportingStatus = 'submitted' | 'in_progress' | 'pending';

interface CbamReport {
  overview: {
    reportingPeriod: string;
    reportingFrequency?: string;
    nextDeadline: string;
    lastSubmitted: string | null;
    exposureLevel: string;
    complianceStatus: CbamComplianceStatus;
    totalEmbeddedEmissions: number;
    totalDirectEmbeddedEmissions?: number;
    totalIndirectEmbeddedEmissions?: number;
    totalExportVolume: number;
    estimatedLiabilityEUR: number;
    readinessScore: number;
    coveredGoodsCount: number;
    methodology?: string;
  };
  goods: Array<{
    id: string;
    name: string;
    hsCode: string;
    exportVolumeTonnes: number;
    embeddedEmissions: number;
    directEmbeddedEmissions?: number;
    indirectEmbeddedEmissions?: number;
    emissionIntensity: number;
    dataQuality: string;
    reportingStatus: CbamReportingStatus;
    estimatedLiabilityEUR: number;
  }>;
  emissionsTrend: Array<{
    period: string;
    directEmbeddedEmissions?: number;
    indirectEmbeddedEmissions?: number;
    embeddedEmissions: number;
    exportVolume: number;
  }>;
  documentation: Array<{
    id: string;
    title: string;
    status: CbamDocumentStatus;
    owner: string;
  }>;
  recommendations: string[];
  msmeProfile: {
    companyName: string;
    industry: string;
    businessDomain: string;
    companyType?: string;
    gstNumber?: string;
    manufacturingUnits?: number;
    numberOfEmployees?: number;
    annualTurnover?: number;
  };
}

interface Iso14064Report {
  overview: {
    readinessScore: number;
    status: string;
    totalCO2Emissions: number;
    confidence: number;
  };
  checks: Array<{ id: string; passed: boolean; actual: string }>;
  visualization?: {
    scopeContribution?: Array<{ scope: string; emissions: number; percentage: number }>;
    qualityBreakdown?: Array<{ metric: string; value: number }>;
    complianceChecks?: Array<{ id: string; label: string; status: string; score: number }>;
    governanceCoverage?: Array<{ id: string; control: string; status: string; score: number }>;
    emissionsTrend?: Array<{ period: string; total: number; scope1: number; scope2: number; scope3: number }>;
  };
}

interface BrsrSectorCarbonAnalytics {
  sectorId: string;
  sectorLabel: string;
  industryContext: {
    industry: string | null;
    businessDomain: string | null;
    industrySector: string | null;
  };
  brsrPrinciple6Highlights: string[];
  sectorBenchmarkNote: string;
  focusCategories: Array<{
    categoryKey: string;
    label: string;
    emissionsKgCO2e: number;
    shareOfCategoryTotalPercent: number;
  }>;
  suggestedActions: string[];
  dataSignals: {
    transactionCount: number;
    assessmentStatus: string;
    categoryDataCompletenessPercent: number;
  };
}

interface BrsrComplianceSummary {
  framework: string;
  disclosureReadinessPercent: number;
  isBRSRCompliant: boolean;
  templateAlignment?: {
    sectionA: { title: string; status: string };
    sectionB: { title: string; status: string };
    sectionC: { title: string; status: string };
  };
  environmentalComplianceScore: number;
  mandatoryFieldGaps: string[];
  principle6EnvironmentalStatus: string | null;
}

interface BrsrReport {
  reportingPeriod?: {
    financialYear?: string;
    startDate?: string | null;
    endDate?: string | null;
  };
  organization?: {
    companyName?: string;
    industry?: string;
    businessDomain?: string;
  };
  environmental?: {
    greenhouseGasEmissions?: {
      total?: number;
      unit?: string;
      scopeContributionPercent?: { scope1: number; scope2: number; scope3: number };
    };
  };
  sectorCarbonAnalytics?: BrsrSectorCarbonAnalytics;
  brsrComplianceSummary?: BrsrComplianceSummary;
}

interface Iso14067Report {
  overview: {
    readinessScore: number;
    status: string;
    functionalUnit: string;
    allocationMethod: string | null;
    confidence: number;
  };
  productFootprint: {
    productCount: number;
    totalProductFootprint: number;
    estimatedFootprintPerFunctionalUnit: number;
    lifecycleCoverage: number;
    boundaryDefinition?: {
      systemBoundaryType?: string;
      rigorScore?: number;
      stageCoverageScore?: number;
      includedStages?: string[];
      excludedStages?: string[];
    };
    lciCoverage?: {
      totalRecords?: number;
      granularityScore?: number;
    };
    uncertaintyProfile?: {
      relativeUncertainty?: number;
      lowerBound?: number;
      upperBound?: number;
    };
  };
  checks: Array<{ id: string; passed: boolean; actual: string }>;
  visualization?: {
    lifecycleStageContribution?: Array<{ stage: string; label: string; emissions: number }>;
    productComparison?: Array<{ productName: string; totalFootprint: number; perFunctionalUnit: number; lciRecords: number }>;
    lciRecordsByStage?: Array<{ stage: string; label: string; records: number }>;
    boundaryCoverage?: Array<{ stage: string; label: string; included: number }>;
    uncertaintyBand?: Array<{ label: string; value: number }>;
  };
}

interface TabPanelProps {
  children: React.ReactNode;
  value: number;
  index: number;
}

function TabPanel({ children, value, index }: TabPanelProps) {
  if (value !== index) return null;
  return <Box sx={{ mt: 2 }}>{children}</Box>;
}

const COLORS = ['#1e88e5', '#43a047', '#f9a825', '#e53935', '#5e35b1', '#00897b'];

const ReportingScreen: React.FC = () => {
  const [tabValue, setTabValue] = useState(0);
  const [dateRange, setDateRange] = useState('6months');
  const [exportDialogOpen, setExportDialogOpen] = useState(false);
  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
  const [email, setEmail] = useState('');
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState('');
  const [snackbarSeverity, setSnackbarSeverity] = useState<'success' | 'error'>('success');

  const [cbamReport, setCbamReport] = useState<CbamReport | null>(null);
  const [iso14064Report, setIso14064Report] = useState<Iso14064Report | null>(null);
  const [iso14067Report, setIso14067Report] = useState<Iso14067Report | null>(null);
  const [brsrReport, setBrsrReport] = useState<BrsrReport | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    const fetchReports = async () => {
      setLoading(true);
      setError(null);

      const cbamPeriodMap: Record<string, string> = {
        '1month': 'month',
        '3months': 'quarter',
        '6months': 'half-year',
        '1year': 'year'
      };
      const isoPeriodMap: Record<string, string> = {
        '1month': 'month',
        '3months': 'quarter',
        '6months': '6months',
        '1year': 'annual'
      };

      const brsrPeriodMap: Record<string, string> = {
        '1month': 'month',
        '3months': 'quarter',
        '6months': '6months',
        '1year': 'annual'
      };

      const [brsrResult, cbamResult, iso64Result, iso67Result] = await Promise.allSettled([
        ApiService.getBRSRReport({ period: brsrPeriodMap[dateRange] || 'annual' }),
        ApiService.getCbamReport({ period: cbamPeriodMap[dateRange] || 'quarter' }),
        ApiService.getISO14064Report({ period: isoPeriodMap[dateRange] || '6months' }),
        ApiService.getISO14067Report({ period: isoPeriodMap[dateRange] || '6months' })
      ]);

      if (!active) return;

      if (brsrResult.status === 'fulfilled') {
        setBrsrReport(brsrResult.value?.data ?? brsrResult.value);
      } else {
        setBrsrReport(null);
      }

      if (cbamResult.status === 'fulfilled') {
        setCbamReport(cbamResult.value?.data ?? cbamResult.value);
      } else {
        setCbamReport(null);
      }

      if (iso64Result.status === 'fulfilled') {
        setIso14064Report(iso64Result.value?.data ?? iso64Result.value);
      } else {
        setIso14064Report(null);
      }

      if (iso67Result.status === 'fulfilled') {
        setIso14067Report(iso67Result.value?.data ?? iso67Result.value);
      } else {
        setIso14067Report(null);
      }

      if (
        brsrResult.status !== 'fulfilled' &&
        cbamResult.status !== 'fulfilled' &&
        iso64Result.status !== 'fulfilled' &&
        iso67Result.status !== 'fulfilled'
      ) {
        setError('Unable to load reporting data.');
      }
      setLoading(false);
    };

    fetchReports();
    return () => {
      active = false;
    };
  }, [dateRange]);

  const exportLabel = useMemo(() => {
    if (tabValue === 4) return 'CBAM (Quarterly Compliance Report) - PDF';
    if (tabValue === 2) return 'ISO 14064 (Organizational Carbon Accounting) - PDF';
    if (tabValue === 3) return 'ISO 14067 (Product Carbon Footprint) - PDF';
    return 'BRSR (Business Responsibility and Sustainability Reporting) - PDF';
  }, [tabValue]);

  const formatNumber = (value: number, decimals = 1) => value.toLocaleString('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  });

  const formatDate = (value: string | null) => {
    if (!value) return 'Not submitted';
    return new Date(value).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
  };

  const formatOptionalNumber = (value?: number, decimals = 0) => {
    if (typeof value !== 'number' || Number.isNaN(value)) return 'N/A';
    return formatNumber(value, decimals);
  };

  const handleExport = async () => {
    const isoPeriodMap: Record<string, string> = {
      '1month': 'month',
      '3months': 'quarter',
      '6months': '6months',
      '1year': 'annual'
    };
    const cbamPeriodMap: Record<string, string> = {
      '1month': 'month',
      '3months': 'quarter',
      '6months': 'half-year',
      '1year': 'year'
    };

    try {
      const brsrPeriodMap: Record<string, string> = {
        '1month': 'month',
        '3months': 'quarter',
        '6months': '6months',
        '1year': 'annual'
      };

      let blob: Blob;
      let fileName = 'BRSR_Report';
      if (tabValue === 2) {
        blob = await ApiService.downloadISO14064ReportPdf({ period: isoPeriodMap[dateRange] || '6months' });
        fileName = 'ISO14064_Report';
      } else if (tabValue === 3) {
        blob = await ApiService.downloadISO14067ReportPdf({ period: isoPeriodMap[dateRange] || '6months' });
        fileName = 'ISO14067_Report';
      } else if (tabValue === 4) {
        blob = await ApiService.downloadCbamReportPdf({ period: cbamPeriodMap[dateRange] || 'quarter' });
        fileName = 'CBAM_Report';
      } else {
        blob = await ApiService.downloadBRSRReportPdf({ period: brsrPeriodMap[dateRange] || 'annual' });
      }

      const blobUrl = window.URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = blobUrl;
      anchor.download = `${fileName}_${new Date().toISOString().slice(0, 10)}.pdf`;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      window.URL.revokeObjectURL(blobUrl);

      setSnackbarMessage('Report exported successfully.');
      setSnackbarSeverity('success');
      setSnackbarOpen(true);
      setExportDialogOpen(false);
    } catch (err: any) {
      setSnackbarMessage(err?.message || 'Failed to export report.');
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    }
  };

  const handleEmailReport = () => {
    setSnackbarMessage(`Report sent to ${email} successfully!`);
    setSnackbarSeverity('success');
    setSnackbarOpen(true);
    setEmailDialogOpen(false);
    setEmail('');
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3, flexWrap: 'wrap', gap: 2 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <Box
            component="img"
            src={BRAND_LOGO_SRC}
            alt="Sustainow Carbon Intelligence"
            sx={{ width: 48, height: 48, flexShrink: 0 }}
          />
          <Box>
            <Typography variant="h4" sx={{ display: 'flex', alignItems: 'center', gap: 1, fontWeight: 700 }}>
              <ReportIcon color="primary" sx={{ display: { xs: 'none', sm: 'inline-flex' } }} />
              Sustainability Reports
            </Typography>
            <Typography variant="body2" color="text.secondary">
              BRSR-aligned disclosures, sector carbon analytics, and international reporting views
            </Typography>
          </Box>
        </Box>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button variant="outlined" startIcon={<DownloadIcon />} onClick={() => setExportDialogOpen(true)}>
            Export
          </Button>
          <Button variant="outlined" startIcon={<EmailIcon />} onClick={() => setEmailDialogOpen(true)}>
            Email
          </Button>
          <Button variant="outlined" startIcon={<PrintIcon />} onClick={() => window.print()}>
            Print
          </Button>
        </Box>
      </Box>

      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <FormControl fullWidth>
                <InputLabel>Date Range</InputLabel>
                <Select value={dateRange} label="Date Range" onChange={(e) => setDateRange(String(e.target.value))}>
                  <MenuItem value="1month">Last Month</MenuItem>
                  <MenuItem value="3months">Last 3 Months</MenuItem>
                  <MenuItem value="6months">Last 6 Months</MenuItem>
                  <MenuItem value="1year">Last Year</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={8}>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                Granular product-level LCI and boundary-rigor reporting is available in ISO 14067 and linked governance/data quality visualizations in ISO 14064.
              </Typography>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {loading && <LinearProgress sx={{ mb: 2 }} />}
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} md={6}>
          <Card sx={{ height: '100%' }}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Company Profile
              </Typography>
              <Box sx={{ mb: 1.5 }}>
                <Typography variant="body2" color="text.secondary">
                  Company Name
                </Typography>
                <Typography variant="body1">{cbamReport?.msmeProfile?.companyName || 'N/A'}</Typography>
              </Box>
              <Box sx={{ mb: 1.5 }}>
                <Typography variant="body2" color="text.secondary">
                  Industry
                </Typography>
                <Typography variant="body1">{cbamReport?.msmeProfile?.industry || 'N/A'}</Typography>
              </Box>
              <Box sx={{ mb: 1.5 }}>
                <Typography variant="body2" color="text.secondary">
                  Business Domain
                </Typography>
                <Typography variant="body1">{cbamReport?.msmeProfile?.businessDomain || 'N/A'}</Typography>
              </Box>
              <Box>
                <Typography variant="body2" color="text.secondary">
                  GST Number
                </Typography>
                <Typography variant="body1" sx={{ fontFamily: 'monospace' }}>
                  {cbamReport?.msmeProfile?.gstNumber || 'N/A'}
                </Typography>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={6}>
          <Card sx={{ height: '100%' }}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Operations
              </Typography>
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <Paper variant="outlined" sx={{ p: 2 }}>
                    <Typography variant="body2" color="text.secondary">
                      Manufacturing Units
                    </Typography>
                    <Typography variant="h6">{formatOptionalNumber(cbamReport?.msmeProfile?.manufacturingUnits)}</Typography>
                  </Paper>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Paper variant="outlined" sx={{ p: 2 }}>
                    <Typography variant="body2" color="text.secondary">
                      Employees
                    </Typography>
                    <Typography variant="h6">{formatOptionalNumber(cbamReport?.msmeProfile?.numberOfEmployees)}</Typography>
                  </Paper>
                </Grid>
                <Grid item xs={12}>
                  <Paper variant="outlined" sx={{ p: 2 }}>
                    <Typography variant="body2" color="text.secondary">
                      Annual Turnover
                    </Typography>
                    <Typography variant="h6">
                      {typeof cbamReport?.msmeProfile?.annualTurnover === 'number'
                        ? `INR ${formatNumber(cbamReport.msmeProfile.annualTurnover, 0)}`
                        : 'N/A'}
                    </Typography>
                  </Paper>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Card>
        <Box sx={{ borderBottom: 1, borderColor: 'divider', px: 2, pt: 2, display: 'flex', gap: 2, flexWrap: 'wrap' }}>
          <Button variant={tabValue === 0 ? 'contained' : 'text'} onClick={() => setTabValue(0)}>
            Overview
          </Button>
          <Button variant={tabValue === 1 ? 'contained' : 'text'} onClick={() => setTabValue(1)}>
            BRSR
          </Button>
          <Button variant={tabValue === 2 ? 'contained' : 'text'} onClick={() => setTabValue(2)}>
            ISO 14064
          </Button>
          <Button variant={tabValue === 3 ? 'contained' : 'text'} onClick={() => setTabValue(3)}>
            ISO 14067
          </Button>
          <Button variant={tabValue === 4 ? 'contained' : 'text'} onClick={() => setTabValue(4)}>
            CBAM
          </Button>
        </Box>
        <TabSectionNavLinks
          tabLabels={[...REPORTING_TAB_LABELS]}
          currentIndex={tabValue}
          onNavigate={setTabValue}
        />

        <TabPanel value={tabValue} index={0}>
          <Grid container spacing={3}>
            <Grid item xs={12} md={3}>
              <Card sx={{ height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">BRSR disclosure readiness</Typography>
                  <Typography variant="h4" color="primary">
                    {formatNumber(brsrReport?.brsrComplianceSummary?.disclosureReadinessPercent ?? 0, 0)}%
                  </Typography>
                  <Chip
                    size="small"
                    sx={{ mt: 1 }}
                    label={brsrReport?.brsrComplianceSummary?.isBRSRCompliant ? 'Meets threshold' : 'Below threshold'}
                    color={brsrReport?.brsrComplianceSummary?.isBRSRCompliant ? 'success' : 'warning'}
                  />
                  <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                    {brsrReport?.reportingPeriod?.financialYear || 'Reporting period'} · SEBI BRSR Core alignment
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={3}>
              <Card sx={{ height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">ISO 14064 readiness</Typography>
                  <Typography variant="h4" color="primary">{formatNumber(iso14064Report?.overview.readinessScore || 0, 0)}%</Typography>
                  <Typography variant="body2">{iso14064Report?.overview.status || 'Unavailable'}</Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={3}>
              <Card sx={{ height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">ISO 14067 readiness</Typography>
                  <Typography variant="h4" color="primary">{formatNumber(iso14067Report?.overview.readinessScore || 0, 0)}%</Typography>
                  <Typography variant="body2">{iso14067Report?.overview.status || 'Unavailable'}</Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} md={3}>
              <Card sx={{ height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle2" color="text.secondary">CBAM readiness</Typography>
                  <Typography variant="h4" color="primary">{formatNumber(cbamReport?.overview.readinessScore || 0, 0)}%</Typography>
                  <Typography variant="body2">{cbamReport?.overview.complianceStatus || 'Unavailable'}</Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12}>
              <Alert severity="info" icon={<ComplianceIcon />}>
                <Typography variant="subtitle2" gutterBottom>BRSR Principle 6 (environment) — sector lens</Typography>
                <Typography variant="body2">
                  {brsrReport?.sectorCarbonAnalytics?.sectorLabel
                    ? `Your profile is classified as ${brsrReport.sectorCarbonAnalytics.sectorLabel}. Open the BRSR tab for disclosure mapping, sector carbon hotspots, and export-ready PDF.`
                    : 'Complete MSME registration and assessments to unlock sector-specific carbon analytics and BRSR compliance tracking.'}
                </Typography>
              </Alert>
            </Grid>
          </Grid>
        </TabPanel>

        <TabPanel value={tabValue} index={1}>
          {!brsrReport ? (
            <Alert severity="info">BRSR report data is not available.</Alert>
          ) : (
            <Grid container spacing={3}>
              <Grid item xs={12} md={4}>
                <Card>
                  <CardContent>
                    <Typography variant="subtitle2" color="text.secondary">Total GHG (reporting period)</Typography>
                    <Typography variant="h4" color="primary">
                      {formatNumber(brsrReport.environmental?.greenhouseGasEmissions?.total || 0, 1)}
                    </Typography>
                    <Typography variant="body2">{brsrReport.environmental?.greenhouseGasEmissions?.unit || 'kgCO2e'}</Typography>
                    <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                      {brsrReport.reportingPeriod?.financialYear || 'FY'} · {brsrReport.organization?.companyName || 'Organization'}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={4}>
                <Card>
                  <CardContent>
                    <Typography variant="subtitle2" color="text.secondary">BRSR disclosure readiness</Typography>
                    <Typography variant="h4" color="primary">
                      {formatNumber(brsrReport.brsrComplianceSummary?.disclosureReadinessPercent ?? 0, 0)}%
                    </Typography>
                    <Typography variant="body2">
                      Env. compliance signals: {formatNumber(brsrReport.brsrComplianceSummary?.environmentalComplianceScore ?? 0, 0)}%
                    </Typography>
                    <Chip
                      size="small"
                      sx={{ mt: 1 }}
                      icon={<ComplianceIcon />}
                      label={brsrReport.brsrComplianceSummary?.isBRSRCompliant ? 'BRSR-ready (≥75%)' : 'Close gaps to reach 75%'}
                      color={brsrReport.brsrComplianceSummary?.isBRSRCompliant ? 'success' : 'warning'}
                    />
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={4}>
                <Card>
                  <CardContent>
                    <Typography variant="subtitle2" color="text.secondary">Principle 6 environmental block</Typography>
                    <Typography variant="body1" sx={{ textTransform: 'capitalize' }}>
                      Status: {String(brsrReport.brsrComplianceSummary?.principle6EnvironmentalStatus || 'n/a').replace(/_/g, ' ')}
                    </Typography>
                    <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                      {brsrReport.brsrComplianceSummary?.framework}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Scope mix (BRSR)</Typography>
                    <ResponsiveContainer width="100%" height={260}>
                      <PieChart>
                        <Pie
                          data={[
                            {
                              name: 'Scope 1',
                              value: brsrReport.environmental?.greenhouseGasEmissions?.scopeContributionPercent?.scope1 ?? 0
                            },
                            {
                              name: 'Scope 2',
                              value: brsrReport.environmental?.greenhouseGasEmissions?.scopeContributionPercent?.scope2 ?? 0
                            },
                            {
                              name: 'Scope 3',
                              value: brsrReport.environmental?.greenhouseGasEmissions?.scopeContributionPercent?.scope3 ?? 0
                            }
                          ]}
                          dataKey="value"
                          nameKey="name"
                          cx="50%"
                          cy="50%"
                          outerRadius={88}
                          label={({ name, value }) => `${name}: ${formatNumber(value, 0)}%`}
                        >
                          {COLORS.map((color, idx) => (
                            <Cell key={`cell-${idx}`} fill={color} />
                          ))}
                        </Pie>
                        <Tooltip formatter={(v: number) => `${formatNumber(v, 1)}%`} />
                        <Legend />
                      </PieChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Sector carbon focus</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                      {brsrReport.sectorCarbonAnalytics?.sectorBenchmarkNote}
                    </Typography>
                    <ResponsiveContainer width="100%" height={220}>
                      <BarChart data={brsrReport.sectorCarbonAnalytics?.focusCategories || []}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="label" interval={0} angle={-18} textAnchor="end" height={72} />
                        <YAxis />
                        <Tooltip formatter={(v: number) => formatNumber(v, 1)} />
                        <Bar dataKey="emissionsKgCO2e" fill="#00897b" name="kgCO2e" />
                      </BarChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Principle 6 narrative hooks</Typography>
                    <Box component="ul" sx={{ m: 0, pl: 2.5 }}>
                      {(brsrReport.sectorCarbonAnalytics?.brsrPrinciple6Highlights || []).map((line, i) => (
                        <Typography key={i} component="li" variant="body2" sx={{ mb: 1 }}>
                          {line}
                        </Typography>
                      ))}
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Suggested next steps</Typography>
                    <Box component="ul" sx={{ m: 0, pl: 2.5 }}>
                      {(brsrReport.sectorCarbonAnalytics?.suggestedActions || []).map((line, i) => (
                        <Typography key={i} component="li" variant="body2" sx={{ mb: 1 }}>
                          {line}
                        </Typography>
                      ))}
                    </Box>
                    <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                      Data completeness (category signals):{' '}
                      {formatNumber(brsrReport.sectorCarbonAnalytics?.dataSignals?.categoryDataCompletenessPercent ?? 0, 0)}% ·
                      Transactions in period: {brsrReport.sectorCarbonAnalytics?.dataSignals?.transactionCount ?? 0}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>BRSR template sections (A–C)</Typography>
                    <TableContainer>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell>Section</TableCell>
                            <TableCell>Title</TableCell>
                            <TableCell>Status</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          <TableRow>
                            <TableCell>A</TableCell>
                            <TableCell>{brsrReport.brsrComplianceSummary?.templateAlignment?.sectionA?.title}</TableCell>
                            <TableCell>
                              <Chip size="small" label={brsrReport.brsrComplianceSummary?.templateAlignment?.sectionA?.status} />
                            </TableCell>
                          </TableRow>
                          <TableRow>
                            <TableCell>B</TableCell>
                            <TableCell>{brsrReport.brsrComplianceSummary?.templateAlignment?.sectionB?.title}</TableCell>
                            <TableCell>
                              <Chip size="small" label={brsrReport.brsrComplianceSummary?.templateAlignment?.sectionB?.status} />
                            </TableCell>
                          </TableRow>
                          <TableRow>
                            <TableCell>C</TableCell>
                            <TableCell>{brsrReport.brsrComplianceSummary?.templateAlignment?.sectionC?.title}</TableCell>
                            <TableCell>
                              <Chip size="small" label={brsrReport.brsrComplianceSummary?.templateAlignment?.sectionC?.status} />
                            </TableCell>
                          </TableRow>
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Mandatory field gaps</Typography>
                    {(brsrReport.brsrComplianceSummary?.mandatoryFieldGaps || []).length === 0 ? (
                      <Typography variant="body2" color="success.main">No mandatory field gaps flagged.</Typography>
                    ) : (
                      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                        {(brsrReport.brsrComplianceSummary?.mandatoryFieldGaps || []).map((gap) => (
                          <Chip key={gap} size="small" color="warning" label={gap.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ')} />
                        ))}
                      </Box>
                    )}
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          )}
        </TabPanel>

        <TabPanel value={tabValue} index={2}>
          {!iso14064Report ? (
            <Alert severity="info">ISO 14064 report is not available.</Alert>
          ) : (
            <Grid container spacing={3}>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Scope contribution</Typography>
                    <ResponsiveContainer width="100%" height={280}>
                      <BarChart data={iso14064Report.visualization?.scopeContribution || []}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="scope" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Bar dataKey="emissions" fill="#1e88e5" name="Emissions (tCO2e)" />
                      </BarChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Data quality</Typography>
                    <ResponsiveContainer width="100%" height={280}>
                      <BarChart data={iso14064Report.visualization?.qualityBreakdown || []}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="metric" />
                        <YAxis domain={[0, 100]} />
                        <Tooltip />
                        <Bar dataKey="value" fill="#43a047" name="Score (%)" />
                      </BarChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Emissions trend by scope</Typography>
                    <ResponsiveContainer width="100%" height={320}>
                      <LineChart data={iso14064Report.visualization?.emissionsTrend || []}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="period" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Line type="monotone" dataKey="total" stroke="#1e88e5" strokeWidth={3} name="Total" />
                        <Line type="monotone" dataKey="scope1" stroke="#e53935" name="Scope 1" />
                        <Line type="monotone" dataKey="scope2" stroke="#f9a825" name="Scope 2" />
                        <Line type="monotone" dataKey="scope3" stroke="#43a047" name="Scope 3" />
                      </LineChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Compliance checks</Typography>
                    <TableContainer>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell>Check</TableCell>
                            <TableCell>Status</TableCell>
                            <TableCell>Actual</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {(iso14064Report.checks || []).map((check) => (
                            <TableRow key={check.id}>
                              <TableCell>{check.id.replace(/_/g, ' ')}</TableCell>
                              <TableCell>
                                <Chip size="small" color={check.passed ? 'success' : 'warning'} label={check.passed ? 'Pass' : 'Gap'} />
                              </TableCell>
                              <TableCell>{check.actual}</TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Governance control coverage</Typography>
                    <ResponsiveContainer width="100%" height={280}>
                      <BarChart data={iso14064Report.visualization?.governanceCoverage || []}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="control" hide />
                        <YAxis domain={[0, 100]} />
                        <Tooltip />
                        <Bar dataKey="score" fill="#5e35b1" name="Control score" />
                      </BarChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          )}
        </TabPanel>

        <TabPanel value={tabValue} index={3}>
          {!iso14067Report ? (
            <Alert severity="info">ISO 14067 report is not available.</Alert>
          ) : (
            <Grid container spacing={3}>
              <Grid item xs={12} md={4}>
                <Card>
                  <CardContent>
                    <Typography variant="subtitle2" color="text.secondary">Product footprint total</Typography>
                    <Typography variant="h4" color="primary">{formatNumber(iso14067Report.productFootprint.totalProductFootprint, 2)}</Typography>
                    <Typography variant="body2">tCO₂e</Typography>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={4}>
                <Card>
                  <CardContent>
                    <Typography variant="subtitle2" color="text.secondary">Boundary rigor score</Typography>
                    <Typography variant="h4" color="primary">{formatNumber(iso14067Report.productFootprint.boundaryDefinition?.rigorScore || 0, 1)}</Typography>
                    <Typography variant="body2">/ 100</Typography>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={4}>
                <Card>
                  <CardContent>
                    <Typography variant="subtitle2" color="text.secondary">LCI granularity score</Typography>
                    <Typography variant="h4" color="primary">{formatNumber(iso14067Report.productFootprint.lciCoverage?.granularityScore || 0, 1)}</Typography>
                    <Typography variant="body2">/ 100</Typography>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Lifecycle stage contribution</Typography>
                    <ResponsiveContainer width="100%" height={280}>
                      <BarChart data={iso14067Report.visualization?.lifecycleStageContribution || []}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="label" />
                        <YAxis />
                        <Tooltip />
                        <Bar dataKey="emissions" fill="#1e88e5" name="Emissions (tCO2e)" />
                      </BarChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Product footprint comparison</Typography>
                    <ResponsiveContainer width="100%" height={280}>
                      <BarChart data={iso14067Report.visualization?.productComparison || []}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="productName" hide />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Bar dataKey="totalFootprint" fill="#43a047" name="Total footprint" />
                        <Bar dataKey="perFunctionalUnit" fill="#f9a825" name="Per functional unit" />
                      </BarChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Boundary stage inclusion map</Typography>
                    <ResponsiveContainer width="100%" height={280}>
                      <BarChart data={iso14067Report.visualization?.boundaryCoverage || []}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="label" />
                        <YAxis domain={[0, 1]} />
                        <Tooltip />
                        <Bar dataKey="included" fill="#5e35b1" name="Included (1=yes)" />
                      </BarChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Uncertainty band</Typography>
                    <ResponsiveContainer width="100%" height={280}>
                      <LineChart data={iso14067Report.visualization?.uncertaintyBand || []}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="label" />
                        <YAxis />
                        <Tooltip />
                        <Line type="monotone" dataKey="value" stroke="#e53935" strokeWidth={3} name="tCO2e" />
                      </LineChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Product-level LCI quality checks</Typography>
                    <TableContainer>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell>Check</TableCell>
                            <TableCell>Status</TableCell>
                            <TableCell>Actual</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {(iso14067Report.checks || []).map((check) => (
                            <TableRow key={check.id}>
                              <TableCell>{check.id.replace(/_/g, ' ')}</TableCell>
                              <TableCell>
                                <Chip size="small" color={check.passed ? 'success' : 'warning'} label={check.passed ? 'Pass' : 'Gap'} />
                              </TableCell>
                              <TableCell>{check.actual}</TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          )}
        </TabPanel>

        <TabPanel value={tabValue} index={4}>
          {!cbamReport ? (
            <Alert severity="info">CBAM reporting data is not available.</Alert>
          ) : (
            <Grid container spacing={3}>
              <Grid item xs={12} md={4}>
                <Card>
                  <CardContent>
                    <Typography variant="subtitle2" color="text.secondary">Readiness score</Typography>
                    <Typography variant="h4" color="primary">{formatNumber(cbamReport.overview.readinessScore, 0)}%</Typography>
                    <Chip
                      size="small"
                      label={cbamReport.overview.complianceStatus}
                      color={cbamReport.overview.complianceStatus === 'On Track' ? 'success' : cbamReport.overview.complianceStatus === 'At Risk' ? 'error' : 'warning'}
                      sx={{ mt: 1 }}
                    />
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12} md={8}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Quarterly embedded emissions trend</Typography>
                    <ResponsiveContainer width="100%" height={280}>
                      <LineChart data={cbamReport.emissionsTrend}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="period" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Line type="monotone" dataKey="embeddedEmissions" stroke="#1e88e5" strokeWidth={3} name="Embedded emissions" />
                        <Line type="monotone" dataKey="directEmbeddedEmissions" stroke="#e53935" name="Direct" />
                        <Line type="monotone" dataKey="indirectEmbeddedEmissions" stroke="#43a047" name="Indirect" />
                      </LineChart>
                    </ResponsiveContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>Covered goods</Typography>
                    <TableContainer component={Paper}>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell>Goods</TableCell>
                            <TableCell>HS Code</TableCell>
                            <TableCell align="right">Embedded (tCO₂)</TableCell>
                            <TableCell align="right">Direct</TableCell>
                            <TableCell align="right">Indirect</TableCell>
                            <TableCell align="right">Liability (EUR)</TableCell>
                            <TableCell>Status</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {cbamReport.goods.map((good) => (
                            <TableRow key={good.id}>
                              <TableCell>{good.name}</TableCell>
                              <TableCell>{good.hsCode}</TableCell>
                              <TableCell align="right">{formatNumber(good.embeddedEmissions, 2)}</TableCell>
                              <TableCell align="right">{formatNumber(good.directEmbeddedEmissions || 0, 2)}</TableCell>
                              <TableCell align="right">{formatNumber(good.indirectEmbeddedEmissions || 0, 2)}</TableCell>
                              <TableCell align="right">{formatNumber(good.estimatedLiabilityEUR, 0)}</TableCell>
                              <TableCell>
                                <Chip size="small" label={good.reportingStatus.replace('_', ' ')} />
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="caption" color="text.secondary">
                      {cbamReport.msmeProfile.companyName} · Next deadline {formatDate(cbamReport.overview.nextDeadline)} · {cbamReport.overview.methodology}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          )}
        </TabPanel>
      </Card>

      <Dialog open={exportDialogOpen} onClose={() => setExportDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            Export Report
            <IconButton onClick={() => setExportDialogOpen(false)}>
              <CloseIcon />
            </IconButton>
          </Box>
        </DialogTitle>
        <DialogContent>
          <Box sx={{ pt: 2 }}>
            <Typography variant="body1" gutterBottom>Export format:</Typography>
            <Button variant="contained" fullWidth sx={{ mt: 2 }}>
              {exportLabel}
            </Button>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setExportDialogOpen(false)}>Cancel</Button>
          <Button onClick={handleExport} variant="contained">Export</Button>
        </DialogActions>
      </Dialog>

      <Dialog open={emailDialogOpen} onClose={() => setEmailDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            Email Report
            <IconButton onClick={() => setEmailDialogOpen(false)}>
              <CloseIcon />
            </IconButton>
          </Box>
        </DialogTitle>
        <DialogContent>
          <Box sx={{ pt: 2 }}>
            <TextField
              fullWidth
              label="Email Address"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              sx={{ mb: 2 }}
            />
            <Typography variant="body2" color="text.secondary">
              The selected report will be sent as a PDF attachment.
            </Typography>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEmailDialogOpen(false)}>Cancel</Button>
          <Button onClick={handleEmailReport} variant="contained" disabled={!email}>Send Report</Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={snackbarOpen}
        autoHideDuration={3500}
        onClose={() => setSnackbarOpen(false)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert onClose={() => setSnackbarOpen(false)} severity={snackbarSeverity} sx={{ width: '100%' }}>
          {snackbarMessage}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ReportingScreen;
