import React, { useState, useEffect } from 'react';
import {
  Typography,
  Grid,
  Card,
  CardContent,
  CardActions,
  Button,
  Box,
  Chip,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Divider,
  Alert,
  LinearProgress,
  Rating
} from '@mui/material';
import {
  ExpandMore as ExpandMoreIcon,
  Park as EcoIcon,
  EnergySavingsLeaf as EnergySavingsLeafIcon,
  Water as WaterIcon,
  Recycling as RecyclingIcon,
  LocalShipping as LocalShippingIcon,
  Factory as FactoryIcon,
  TrendingUp as TrendingUpIcon,
  CheckCircle as CheckCircleIcon,
  Schedule as ScheduleIcon,
  AttachMoney as AttachMoneyIcon,
  Timeline as TimelineIcon
} from '@mui/icons-material';
import ApiService from "../services/api";

interface Recommendation {
  id: string;
  title: string;
  category: string;
  priority: 'high' | 'medium' | 'low';
  impact: number; // 1-5 scale
  cost: 'low' | 'medium' | 'high';
  timeline: 'immediate' | 'short-term' | 'medium-term' | 'long-term';
  description: string;
  benefits: string[];
  implementation: string[];
  estimatedSavings: number;
  co2Reduction: number;
  paybackPeriod: number; // in months
}

const normalizeRecommendation = (input: any, index: number): Recommendation => ({
  id: String(input?.id || input?._id || `rec-${index}`),
  title: String(input?.title || 'Untitled recommendation'),
  category: String(input?.category || 'Other'),
  priority: (input?.priority === 'high' || input?.priority === 'medium' || input?.priority === 'low')
    ? input.priority
    : 'low',
  impact: Number.isFinite(input?.impact) ? Number(input.impact) : 0,
  cost: (input?.cost === 'low' || input?.cost === 'medium' || input?.cost === 'high')
    ? input.cost
    : 'low',
  timeline: (
    input?.timeline === 'immediate' ||
    input?.timeline === 'short-term' ||
    input?.timeline === 'medium-term' ||
    input?.timeline === 'long-term'
  )
    ? input.timeline
    : 'short-term',
  description: String(input?.description || ''),
  benefits: Array.isArray(input?.benefits) ? input.benefits : [],
  implementation: Array.isArray(input?.implementation) ? input.implementation : [],
  estimatedSavings: Number(input?.estimatedSavings || 0),
  co2Reduction: Number(input?.co2Reduction || input?.potentialCO2Reduction || 0),
  paybackPeriod: Number(input?.paybackPeriod || 0),
});

const Recommendations: React.FC = () => {
  const [msmeData, setMsmeData] = useState<any>(null);
  const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const profileResponse = await ApiService?.getMSMEProfile();
        if (profileResponse?.data) {
          setMsmeData(profileResponse.data);
          const recommendationResponse = await ApiService.getRecommendations();
          const apiRecommendations = recommendationResponse?.data?.recommendations;
          setRecommendations(
            Array.isArray(apiRecommendations)
              ? apiRecommendations.map((item, index) => normalizeRecommendation(item, index))
              : []
          );
        }
      } catch (err) {
        setMsmeData(null);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case 'Energy': return <EnergySavingsLeafIcon />;
      case 'Waste': return <RecyclingIcon />;
      case 'Water': return <WaterIcon />;
      case 'Transportation': return <LocalShippingIcon />;
      case 'Manufacturing': return <FactoryIcon />;
      case 'Supply Chain': return <TrendingUpIcon />;
      case 'Culture': return <EcoIcon />;
      default: return <EcoIcon />;
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'error';
      case 'medium': return 'warning';
      case 'low': return 'success';
      default: return 'default';
    }
  };

  const getCostColor = (cost: string) => {
    switch (cost) {
      case 'high': return 'error';
      case 'medium': return 'warning';
      case 'low': return 'success';
      default: return 'default';
    }
  };

  const getTimelineIcon = (timeline: string) => {
    switch (timeline) {
      case 'immediate': return <CheckCircleIcon />;
      case 'short-term': return <TimelineIcon />;
      case 'medium-term': return <ScheduleIcon />;
      case 'long-term': return <AttachMoneyIcon />;
      default: return <ScheduleIcon />;
    }
  };

  const filteredRecommendations = selectedCategory === 'all'
    ? recommendations
    : recommendations.filter(rec => rec.category === selectedCategory);

  const categories = ['all', ...Array.from(new Set(recommendations.map(rec => rec.category)))];

  if (!msmeData) {
    return (
      <Alert severity="info" sx={{ mt: 2 }}>
        Please complete MSME registration first to access personalized recommendations.
      </Alert>
    );
  }

  if (isLoading) {
    return (
      <Box sx={{ mt: 4 }}>
        <LinearProgress sx={{ mb: 2 }} />
        <Typography variant="h6" align="center">
          Generating personalized recommendations...
        </Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" component="h1" gutterBottom>
        Sustainable Manufacturing Recommendations
      </Typography>
      <Typography variant="body1" color="text.secondary" paragraph>
        Personalized recommendations to help {msmeData.companyName} reduce carbon footprint and improve sustainability.
      </Typography>

      {/* Category Filter */}
      <Box sx={{ mb: 3 }}>
        <Typography variant="h6" gutterBottom>
          Filter by Category
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {categories.map((category) => (
            <Chip
              key={category}
              label={category === 'all' ? 'All Categories' : category}
              onClick={() => setSelectedCategory(category)}
              color={selectedCategory === category ? 'primary' : 'default'}
              variant={selectedCategory === category ? 'filled' : 'outlined'}
            />
          ))}
        </Box>
      </Box>

      {/* Recommendations List */}
      <Grid container spacing={3}>
        {filteredRecommendations.map((recommendation) => (
          <Grid item xs={12} key={recommendation.id}>
            <Accordion>
              <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                <Box sx={{ width: '100%', display: 'flex', alignItems: 'center', gap: 2 }}>
                  {getCategoryIcon(recommendation.category)}
                  <Box sx={{ flexGrow: 1 }}>
                    <Typography variant="h6">
                      {recommendation.title}
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                      <Chip
                        label={recommendation.priority.toUpperCase()}
                        color={getPriorityColor(recommendation.priority) as any}
                        size="small"
                      />
                      <Chip
                        label={`${recommendation.cost.toUpperCase()} COST`}
                        color={getCostColor(recommendation.cost) as any}
                        size="small"
                      />
                      <Chip
                        label={recommendation.timeline.toUpperCase()}
                        color="info"
                        size="small"
                        icon={getTimelineIcon(recommendation.timeline)}
                      />
                    </Box>
                  </Box>
                  <Box sx={{ textAlign: 'right' }}>
                    <Typography variant="h6" color="primary">
                      ₹{recommendation.estimatedSavings.toLocaleString()}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Annual Savings
                    </Typography>
                  </Box>
                </Box>
              </AccordionSummary>
              <AccordionDetails>
                <Grid container spacing={3}>
                  <Grid item xs={12} md={8}>
                    <Typography variant="body1" paragraph>
                      {recommendation.description}
                    </Typography>

                    <Typography variant="h6" gutterBottom>
                      Benefits
                    </Typography>
                    <List dense>
                      {recommendation.benefits.map((benefit, index) => (
                        <ListItem key={index}>
                          <ListItemIcon>
                            <CheckCircleIcon color="success" />
                          </ListItemIcon>
                          <ListItemText primary={benefit} />
                        </ListItem>
                      ))}
                    </List>

                    <Typography variant="h6" gutterBottom sx={{ mt: 2 }}>
                      Implementation Steps
                    </Typography>
                    <List dense>
                      {recommendation.implementation.map((step, index) => (
                        <ListItem key={index}>
                          <ListItemText
                            primary={`${index + 1}. ${step}`}
                            primaryTypographyProps={{ variant: 'body2' }}
                          />
                        </ListItem>
                      ))}
                    </List>
                  </Grid>

                  <Grid item xs={12} md={4}>
                    <Card variant="outlined">
                      <CardContent>
                        <Typography variant="h6" gutterBottom>
                          Impact Metrics
                        </Typography>

                        <Box sx={{ mb: 2 }}>
                          <Typography variant="body2" color="text.secondary">
                            Environmental Impact
                          </Typography>
                          <Rating value={recommendation.impact} readOnly size="small" />
                          <Typography variant="body2" sx={{ mt: 1 }}>
                            {recommendation.co2Reduction} kg CO₂ reduction/year
                          </Typography>
                        </Box>

                        <Divider sx={{ my: 2 }} />

                        <Box sx={{ mb: 2 }}>
                          <Typography variant="body2" color="text.secondary">
                            Financial Impact
                          </Typography>
                          <Typography variant="h6" color="success">
                            ₹{recommendation.estimatedSavings.toLocaleString()}
                          </Typography>
                          <Typography variant="body2">
                            Annual savings
                          </Typography>
                        </Box>

                        <Divider sx={{ my: 2 }} />

                        <Box sx={{ mb: 2 }}>
                          <Typography variant="body2" color="text.secondary">
                            Payback Period
                          </Typography>
                          <Typography variant="h6">
                            {recommendation.paybackPeriod} months
                          </Typography>
                        </Box>

                        <CardActions>
                          <Button
                            variant="contained"
                            fullWidth
                            startIcon={<EcoIcon />}
                          >
                            Implement This
                          </Button>
                        </CardActions>
                      </CardContent>
                    </Card>
                  </Grid>
                </Grid>
              </AccordionDetails>
            </Accordion>
          </Grid>
        ))}
      </Grid>

      {filteredRecommendations.length === 0 && (
        <Alert severity="info" sx={{ mt: 3 }}>
          No recommendations are available yet. Complete a carbon assessment to generate recommendations.
        </Alert>
      )}

      {/* Summary */}
      <Card sx={{ mt: 4 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Implementation Summary
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} sm={4}>
              <Box textAlign="center">
                <Typography variant="h4" color="primary">
                  {filteredRecommendations.length}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Recommendations
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Box textAlign="center">
                <Typography variant="h4" color="success">
                  ₹{filteredRecommendations.reduce((sum, rec) => sum + rec.estimatedSavings, 0).toLocaleString()}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Total Annual Savings
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Box textAlign="center">
                <Typography variant="h4" color="info">
                  {filteredRecommendations.reduce((sum, rec) => sum + rec.co2Reduction, 0)} kg
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  CO₂ Reduction Potential
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    </Box>
  );
};

export default Recommendations;